DeviceBuffer varied(std::size_t n, unsigned seed) {
    std::vector<__nv_bfloat16> values(n);
    for (auto& v : values) {
        seed = seed * 1664525U + 1013904223U;
        v    = __float2bfloat16(static_cast<float>(seed >> 8) * (2.0f / 16777216.0f) - 1.0f);
